using FluentAssertions;using Microsoft.EntityFrameworkCore;using SmartHotel.HotelOps.API.Services;using SmartHotel.HotelOps.Domain.Entities;using SmartHotel.HotelOps.Domain.Enums;using SmartHotel.HotelOps.Infrastructure.Persistence;
namespace SmartHotel.HotelOps.Tests;
public class MaintenanceRestrictionTests{
 [Fact]public async Task RestrictAndClearWithoutHousekeepingApproval_ReturnsRoomToDirty(){await using var db=Context();var room=Room(RoomStatus.Available);db.Rooms.Add(room);await db.SaveChangesAsync();var service=new MaintenanceRestrictionService(db);var work=Guid.NewGuid();var dept=Guid.NewGuid();var at=DateTime.UtcNow;var restricted=await service.Restrict(room.Id,new(work,Guid.NewGuid(),dept,Guid.NewGuid(),"Water leak","High",true,at),default);restricted.RoomStatus.Should().Be("OutOfOrder");var cleared=await service.Clear(room.Id,new(work,Guid.NewGuid(),dept,Guid.NewGuid(),at.AddHours(1)),default);cleared.RoomStatus.Should().Be("Dirty");cleared.HousekeepingApproved.Should().BeFalse();}
 [Fact]public async Task ActiveRestriction_BlocksAvailabilityUntilManagerClearance(){await using var db=Context();var room=Room(RoomStatus.InCleaning);var task=Guid.NewGuid();var hkDept=Guid.NewGuid();var started=DateTime.UtcNow;db.AddRange(room,new HousekeepingReadiness{TaskId=task,RoomId=room.Id,DepartmentId=hkDept,HousekeeperId=Guid.NewGuid(),Status=HousekeepingReadinessStatus.CleaningStarted,StartedAtUtc=started});await db.SaveChangesAsync();var maintenance=new MaintenanceRestrictionService(db);var work=Guid.NewGuid();var maintenanceDept=Guid.NewGuid();await maintenance.Restrict(room.Id,new(work,Guid.NewGuid(),maintenanceDept,Guid.NewGuid(),"Electrical hazard","Critical",true,started.AddMinutes(1)),default);var housekeeping=new HousekeepingReadinessService(db);var inspected=await housekeeping.InspectAsync(room.Id,new(task,Guid.NewGuid(),hkDept,Guid.NewGuid(),true,"Clean",started.AddMinutes(30)),default);inspected.RoomStatus.Should().Be("OutOfOrder");var cleared=await maintenance.Clear(room.Id,new(work,Guid.NewGuid(),maintenanceDept,Guid.NewGuid(),started.AddHours(1)),default);cleared.RoomStatus.Should().Be("Available");cleared.HousekeepingApproved.Should().BeTrue();}
 [Fact]public async Task DuplicateRestrictionEvent_IsIdempotent(){await using var db=Context();var room=Room(RoomStatus.Available);db.Rooms.Add(room);await db.SaveChangesAsync();var service=new MaintenanceRestrictionService(db);var e=Guid.NewGuid();var request=new RestrictRoomRequest(Guid.NewGuid(),e,Guid.NewGuid(),Guid.NewGuid(),"AC failure","Medium",false,DateTime.UtcNow);await service.Restrict(room.Id,request,default);var duplicate=await service.Restrict(room.Id,request,default);duplicate.Idempotent.Should().BeTrue();}
 static HotelOpsDbContext Context()=>new(new DbContextOptionsBuilder<HotelOpsDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options);static Room Room(RoomStatus status)=>new(){Id=Guid.NewGuid(),HotelId=Guid.NewGuid(),RoomTypeId=Guid.NewGuid(),RoomNumber="M-1",Status=status};
}
